# Spectral norms of value/out projections across layers (power iteration, ~40 steps)
import torch
def spec(w, iters=50, seed=0):
    torch.manual_seed(seed)
    u=torch.randn(w.shape[0]); u/=u.norm()
    for _ in range(iters):
        v=w.T@u; v/=v.norm(); u=w@v; u/=u.norm()
    return float(u@w@v)
